import{_ as a,o as t,c as o,a0 as r}from"./chunks/framework.tVbs9ddD.js";const p=JSON.parse('{"title":"Explanation: architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),s={name:"explanation/architecture.md"};function i(n,e,d,c,l,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="explanation-architecture" tabindex="-1">Explanation: architecture <a class="header-anchor" href="#explanation-architecture" aria-label="Permalink to &quot;Explanation: architecture&quot;">​</a></h1><h2 id="tiered-memory-not-one-big-summary" tabindex="-1">Tiered memory, not one big summary <a class="header-anchor" href="#tiered-memory-not-one-big-summary" aria-label="Permalink to &quot;Tiered memory, not one big summary&quot;">​</a></h2><p>A monolithic repo summary fails twice: too coarse to plan with, or too big for context. kuda produces a hierarchy agents zoom into:</p><ul><li><strong>L0 — repo card</strong> (<code>index.yaml</code>, ~1k tokens): purpose, module map, entry points, build/test commands. Always-loadable.</li><li><strong>L1 — module cards</strong> (<code>modules/*.yaml</code>): API surface, deps, invariants, <code>verify:</code> file list. Fetched when planning.</li><li><strong>L2 — symbol/dep graph</strong> (<code>index.sqlite</code>): symbol -&gt; file:line and dep edges both directions. Queried, not loaded.</li><li><strong>L3 — source</strong>: the code. Memory indexes it; never replaces it.</li></ul><h2 id="provenance-is-the-staleness-model" tabindex="-1">Provenance is the staleness model <a class="header-anchor" href="#provenance-is-the-staleness-model" aria-label="Permalink to &quot;Provenance is the staleness model&quot;">​</a></h2><p>Every card records <code>{files, content_hash, commit_sha}</code>. <code>kuda status</code> diffs the recorded sha against HEAD — drift is a property of the data, not a promise in prose. <code>sync</code> regenerates only cards whose <code>files</code> changed.</p><h2 id="ports-and-adapters" tabindex="-1">Ports and adapters <a class="header-anchor" href="#ports-and-adapters" aria-label="Permalink to &quot;Ports and adapters&quot;">​</a></h2><p>Every concern is a trait crate + adapter crates (ADR-0001):</p><ul><li>extract: <code>manifest</code> (free, no parser) -&gt; <code>treesitter</code> (grammar+query data) -&gt; <code>lsp</code> (cross-file refs where a server exists)</li><li>summarize: <code>template</code> (deterministic default) | <code>llm</code> (opt-in prose — provider key stays in env/keyring)</li><li>store: <code>sqlite</code> (rebuildable, gitignored)</li><li>serve: <code>cli</code> | <code>mcp</code></li></ul><h2 id="language-as-data" tabindex="-1">Language as data <a class="header-anchor" href="#language-as-data" aria-label="Permalink to &quot;Language as data&quot;">​</a></h2><p>Per-language knowledge — grammar refs, symbol queries, manifest kinds — lives in <code>data/langs/*</code>, not in extractor code. A new language is a data change; the engine&#39;s vocabulary is fixed.</p><h2 id="trust-model" tabindex="-1">Trust model <a class="header-anchor" href="#trust-model" aria-label="Permalink to &quot;Trust model&quot;">​</a></h2><p>Cards end with <code>verify:</code> — the files an agent should open before acting on the card. Memory is a hypothesis that narrows the search space; the code remains the only truth.</p>',13)])])}const u=a(s,[["render",i]]);export{p as __pageData,u as default};
